<?php

/* @autogenerated */
declare(strict_types=1);

namespace Tests\integration\Features\OAuth\Stub;

use DateTimeImmutable;
use Override;
use Civi\Lughauth\Features\OAuth\MagicLink\Domain\MagicLink;
use Civi\Lughauth\Features\OAuth\MagicLink\Domain\Gateway\MagicLinkGateway;

final class InMemoryMagicLinkGateway implements MagicLinkGateway
{
    /** @var array<string, MagicLink> keyed by tokenHash */
    private array $links = [];

    #[Override]
    public function store(MagicLink $magicLink): void
    {
        $this->links[$magicLink->tokenHash] = $magicLink;
    }

    #[Override]
    public function findByHash(string $tokenHash, string $tenantId): ?MagicLink
    {
        $link = $this->links[$tokenHash] ?? null;
        if ($link === null || $link->tenantId !== $tenantId) {
            return null;
        }
        return $link;
    }

    #[Override]
    public function markUsed(string $uid): void
    {
        foreach ($this->links as $hash => $link) {
            if ($link->uid === $uid) {
                $this->links[$hash] = new MagicLink(
                    uid: $link->uid,
                    tenantId: $link->tenantId,
                    userUid: $link->userUid,
                    clientId: $link->clientId,
                    tokenHash: $link->tokenHash,
                    redirectUri: $link->redirectUri,
                    scope: $link->scope,
                    state: $link->state,
                    nonce: $link->nonce,
                    createdAt: $link->createdAt,
                    expiresAt: $link->expiresAt,
                    usedAt: new DateTimeImmutable(),
                );
                return;
            }
        }
    }

    public function last(): ?MagicLink
    {
        if ($this->links === []) {
            return null;
        }
        return end($this->links);
    }

    public function storeExpired(MagicLink $magicLink): void
    {
        $expired = new MagicLink(
            uid: $magicLink->uid,
            tenantId: $magicLink->tenantId,
            userUid: $magicLink->userUid,
            clientId: $magicLink->clientId,
            tokenHash: $magicLink->tokenHash,
            redirectUri: $magicLink->redirectUri,
            scope: $magicLink->scope,
            state: $magicLink->state,
            nonce: $magicLink->nonce,
            createdAt: $magicLink->createdAt,
            expiresAt: new DateTimeImmutable('-1 hour'),
            usedAt: null,
        );
        $this->links[$expired->tokenHash] = $expired;
    }
}
